# Reproducer: the backfill tells release, rc and ARM-branch PRs to retarget to quattro

Four real open PRs (2026-09-30) with intentional non-quattro bases, plus one quattro PR as a control.

Reviewed head: `609a4f40b0f82b8ec7ead48a51fd8d781a2d7e23`. Offline: the script extracts the two `script: |` blocks from the workflow and runs them the way `actions/github-script` does (`new AsyncFunction(...)`), with stubbed `github`, `context` and `core`. No network or token. Run with Node 20 or later from a checkout of the PR head.

**repro.js**

```js
// Offline reproducer for .github/workflows/warn-wrong-pr-base.yml (no network, no token).
// Runs the workflow's `script:` blocks the way actions/github-script does
// (new AsyncFunction(argNames..., source)) with stubbed github/context/core.
// Usage: node repro.js .github/workflows/warn-wrong-pr-base.yml <wrong-base|limit-zero|reopen>
'use strict';
const fs = require('fs');
const AsyncFunction = Object.getPrototypeOf(async () => null).constructor;
const [file, mode] = process.argv.slice(2);

// Extract DEFAULT_BRANCH and the two literal `script: |` blocks (warn first, backfill second).
const lines = fs.readFileSync(file, 'utf8').split('\n');
const defaultBranch = lines.find(l => /^  DEFAULT_BRANCH: /.test(l)).split(': ')[1].trim();
const blocks = [];
for (let i = 0; i < lines.length; i++) {
  const m = /^(\s*)script: \|\s*$/.exec(lines[i]);
  if (!m) continue;
  const body = [];
  let indent = null;
  for (i++; i < lines.length; i++) {
    const l = lines[i];
    if (l.trim() === '') { body.push(''); continue; }
    const ind = l.length - l.trimStart().length;
    if (indent === null) indent = ind;
    if (ind < indent || ind <= m[1].length) { i--; break; }
    body.push(l.slice(indent));
  }
  blocks.push(body.join('\n'));
}
const [warnScript, backfillScript] = blocks;

async function run(source, payload, pulls, comments) {
  const posted = [];
  const github = {
    rest: {
      pulls: { list: async () => ({ data: pulls }) },
      issues: {
        listComments: async p => ({ data: comments[p.issue_number] || [] }),
        createComment: async p => {
          posted.push(p.issue_number);
          (comments[p.issue_number] ||= []).push({ user: { login: 'github-actions[bot]' }, body: p.body });
        },
      },
    },
    paginate: async (method, params) => (await method(params)).data,
  };
  const context = {
    payload,
    repo: { owner: 'omacom', repo: 'omarchy' },
    get issue() { return { ...this.repo, number: (payload.pull_request || payload).number }; },
  };
  const notices = [];
  const core = { notice: m => notices.push(m) };
  process.env.DEFAULT_BRANCH = defaultBranch;
  const instant = fn => fn(); // skip the 1 s pause between comments
  await new AsyncFunction('github', 'context', 'core', 'setTimeout', source)(github, context, core, instant);
  return { posted, notices };
}

(async () => {
  if (mode === 'wrong-base') {
    // Open PRs on 2026-09-30 whose base is a release, rc or ARM port branch.
    const pulls = [
      { number: 13766, base: { ref: 'quattro' }, title: 'Fix stale VS Code theme assertions in test/cli' }, // control
      { number: 13902, base: { ref: 'v4-0-4' }, title: '[4.0.4 backport] Only force NVIDIA VA-API/GLX env when NVIDIA drives the display' },
      { number: 13426, base: { ref: 'dragon' }, title: 'Boot the DGX Spark without a UKI until Limine is fixed' },
      { number: 9073, base: { ref: 'rc' }, title: 'Backport constrained Quattro ownership bootstrap to rc' },
      { number: 8042, base: { ref: 'v4-0-1' }, title: "Regenerate mise wrappers that still print mise's output to stdout (backport of #8041)" },
    ];
    const comments = {};
    const r = await run(backfillScript, { inputs: { limit: '500' } }, pulls, comments);
    for (const p of pulls) console.log(`#${p.number} (${p.base.ref}) ${p.title}\n  -> ${JSON.stringify(comments[p.number]?.[0]?.body ?? null)}`);
    console.log(r.notices.join('\n'));
  } else if (mode === 'limit-zero') {
    const pulls = Array.from({ length: 600 }, (_, i) => ({ number: 1000 + i, base: { ref: 'dev' } }));
    for (const limit of ['0', '-1', '1']) {
      const r = await run(backfillScript, { inputs: { limit } }, pulls, {});
      console.log(`limit input ${JSON.stringify(limit)}: ${r.posted.length} comments posted`);
    }
  } else if (mode === 'reopen') {
    const pr = { number: 30, base: { ref: 'dev' } };
    const comments = {};
    await run(warnScript, { action: 'opened', pull_request: pr }, [], comments);
    await run(warnScript, { action: 'reopened', pull_request: pr }, [], comments);
    console.log(`comments on #30 after opened + reopened: ${comments[30].length}`);
    comments[30].forEach((c, i) => console.log(`${i + 1}. ${JSON.stringify(c.body)}`));
  } else {
    throw new Error('mode must be wrong-base, limit-zero or reopen');
  }
})().catch(e => { console.error(e); process.exit(2); });
```

